param([string]$ReportPath="$PSScriptRoot/../../../evidence/engine-extension/pool-managed-expansion-audit.json")
$ErrorActionPreference='Stop'
$r=Get-Content -LiteralPath $ReportPath -Raw | ConvertFrom-Json
function Finding($id,$claim,$methods,$requirement){[ordered]@{id=$id;status='observed-static';claim=$claim;methodEvidence=$methods;patchRequirement=$requirement}}
$r.proposedCapacity=4080
$r.findings=@(
 (Finding 'managed-index-width' 'Agent.Index and AgentCreationResult.Index are Int32. AgentHelper.GetAgentIndex directly reads a native int32 via ldind.i4; the native pool free-index table being int16 does not make the Agent object index int16.' @('TaleWorlds.MountAndBlade.Agent::get_Index():0x0600098b IL_0001','TaleWorlds.MountAndBlade.AgentHelper::GetAgentIndex(System.UIntPtr):IL_0009') 'Preserve int32 native object field representation and the existing managed ABI. Do not widen the object index or change struct layout merely because pool bookkeeping uses short indices.'),
 (Finding 'pointer-lifetime' 'Agent constructor retains 13 native pointers in fields at IL_0078 through IL_0108, calls IMBAgent.SetMonoObject at IL_0130, and AgentHelper dereferences those pointers directly. All stores found to these fields across scanned assemblies belong to Agent constructor or Agent.Clear; no relocation refresh method was found by this direct-field-reference scan.' @('TaleWorlds.MountAndBlade.Agent::.ctor','TaleWorlds.MountAndBlade.Agent::Clear','TaleWorlds.MountAndBlade.AgentHelper::GetAgentPosition','TaleWorlds.MountAndBlade.AgentHelper::GetAgentState') 'Choose final pool storage before first Mission/Agent construction, keep addresses stable through deletion, and retain SetMonoObject reverse links. Reject live pool relocation; runtime patch removal must wait until all modified-layout missions are destroyed.'),
 (Finding 'native-lookup-contract' 'Mission.FindAgentWithIndexAux rejects only negative indices and otherwise forwards Int32 to native lookup. Managed code provides no upper bound.' @('TaleWorlds.MountAndBlade.Mission::FindAgentWithIndexAux:0x060019b5 IL_0000..IL_0010') 'Audit native FindAgentWithIndex callback474 (0x18070b150), all index-derived pointer arithmetic, and SetMonoObject callback208 (0x1806f7460). Validate both highest valid index and rejection of index4080 before deployment.'),
 (Finding 'singleplayer-capacity-cache' 'DefaultBattleMissionAgentSpawnLogic.MaxNumberOfAgentsForMission caches the native getter on first use when its static cache is zero.' @('TaleWorlds.MountAndBlade.DefaultBattleMissionAgentSpawnLogic::get_MaxNumberOfAgentsForMission:0x0600237c IL_0000..IL_001b') 'Apply the full native layout and getter patch before first read. Verify the cache agrees with the native patched capacity; do not claim getter replacement updates an already initialized cache.'),
 (Finding 'troop-quota' 'MaxNumberOfTroopsForMission returns MaxNumberOfAgentsForMission / 2. A capacity4080 therefore makes this quota2040, not4080.' @('TaleWorlds.MountAndBlade.DefaultBattleMissionAgentSpawnLogic::get_MaxNumberOfTroopsForMission:0x0600237d IL_0005..IL_0006','TaleWorlds.MountAndBlade.DefaultBattleMissionAgentSpawnLogic::CheckMinimumBatchQuotaRequirement','TaleWorlds.MountAndBlade.MissionBattleSideSpawnContext::TryReinforcementSpawn') 'Treat human troop quota and native slots separately. Any quota override needs explicit horse/rider and retiring/dead-agent accounting; retain conservative behavior until this is implemented.'),
 (Finding 'multiplayer-capacity-cache' 'SpawningBehaviorBase static constructor stores the native getter in _maxAgentCount and computes _agentCountThreshold=(int)(maximum*0.9f). OnTick uses both fields.' @('TaleWorlds.MountAndBlade.SpawningBehaviorBase::.cctor:0x060029c0 IL_0005..IL_001c','TaleWorlds.MountAndBlade.SpawningBehaviorBase::OnTick') 'Initial experiment must remain offline. Future multiplayer integration must initialize/rebuild both cached quantities consistently, in addition to protocol changes.'),
 (Finding 'managed-agent-lists' 'Mission constructor initializes active/all AgentList collections with capacity256. AgentList -> AgentReadOnlyList -> MBReadOnlyList<Agent> -> System.Collections.Generic.List<T>, whose constructor receives this initial capacity. These are not fixed2040 arrays.' @('TaleWorlds.MountAndBlade.Mission::.ctor IL_019f..IL_01b9','TaleWorlds.MountAndBlade.Missions.AgentList::.ctor(System.Int32)','TaleWorlds.MountAndBlade.Missions.AgentReadOnlyList::.ctor(System.Int32):0x060036b2','TaleWorlds.Library.MBReadOnlyList`1::.ctor(System.Int32):0x060003e6') 'No capacity patch identified for these two managed lists. This does not establish that all native or third-party per-agent arrays are dynamically sized.'),
 (Finding 'wire-and-recording-width' 'CompressionMission.AgentCompressionInfo is Integer(-1,11); constructor computes maximum=-1+(1<<11)-1=2046. ReadAgentIndexFromPacket and WriteAgentIndexToPacket use it, and BotData.OnRead/OnWrite directly use the same descriptor. The proposed4080 valid indices0..4079 plus -1 need4081 code points and fit12 bits (maximum4094). A later4096 capacity would instead need4097 code points and13 bits.' @('TaleWorlds.MountAndBlade.CompressionMission::.cctor IL_0016..IL_001e','TaleWorlds.MountAndBlade.CompressionInfo/Integer::.ctor(System.Int32,System.Int32):0x06003e58','TaleWorlds.MountAndBlade.Network.Messages.GameNetworkMessage::ReadAgentIndexFromPacket:0x060035c9','TaleWorlds.MountAndBlade.Network.Messages.GameNetworkMessage::WriteAgentIndexToPacket:0x060035ca','NetworkMessages.FromServer.BotData::OnRead','NetworkMessages.FromServer.BotData::OnWrite') 'Do not change this field for the initial offline patch. Reject network, replay and recording modes. A future change needs native packet/replay format audit and matching endpoints, not only managed bit-count replacement.'),
 (Finding 'offline-guard' 'GameNetwork.IsMultiplayerOrReplay excludes SingleRecord. IsServerOrRecorder separately recognizes game type5. MBCommon.GameType enum metadata: Single0, MultiClient1, MultiServer2, MultiClientServer3, SingleReplay4, SingleRecord5.' @('TaleWorlds.MountAndBlade.GameNetwork::get_IsMultiplayerOrReplay:0x06002af0','TaleWorlds.MountAndBlade.GameNetwork::get_IsServerOrRecorder:0x06002ae9') 'Allow only MBCommon.CurrentGameType==Single(0) at mission creation and prevent subsequent transitions into recording/network/replay while modified-layout missions exist. A startup-only network check is insufficient for later mode changes.'),
 (Finding 'bounded-negative-scan' 'Across74 managed assemblies and174607 method bodies, no literal ldc.i4 values2039,2040,2046,2047 or4095 appeared. The one2041 match registers QuestStates as a save-type identifier, not pool capacity. No method with Agent.get_Index and conv.i2/conv.u2 was found. No exact newarr Agent appeared. Candidate arrays/narrow fields are retained, not automatically classified as safe.' @('capacityConstantCandidates','agentIndexNarrowingCandidates','managedArrayCandidates','narrowIndexFieldCandidates') 'Do not blanket-replace numeric constants. Arithmetic-derived capacities, packed bits, reflection, native arrays and third-party mods are outside these negative conclusions.')
)
$r.unknowns=@(
 'Completeness of native fixed-offset references, pool-relative aliases, secondary agent pool role, companion state roles, allocation alignment, destructor unwinding and all object-index consumers.',
 'Native collision, physics, AI jobs, parallel scheduling, render/skeleton arrays, stack scratch buffers, bitsets and index masks may impose independent capacities; managed CIL cannot clear them.',
 'Native recording/replay serialization and direct engine network encoding beyond the observed managed AgentCompressionInfo descriptor are unaudited.',
 'Third-party mod assemblies and binaries outside the enumerated74 artifacts are excluded; arithmetic-derived capacities and unsafe native data flows are not exhaustively identified.',
 'Static evidence does not prove frame time, race freedom, successful slot4079 creation/deletion/reuse, destructor safety, mission reload safety, rendering capacity or cleanup correctness.',
 'No game launched, no module deployed, no assembly patched, and no native cap expansion certified by this audit.'
)
$r | Add-Member -Force -NotePropertyMembers @{
 nativeCallbackJoins=@(
  @{id=208;api='IMBAgent.SetMonoObject';setterBlock='IL_209a';setterAssignment='IL_20af';nativeEntry='0x1806f7460';registration='0x1806445b4';evidence='ev_9e9945bb81c2694f4088be078e0583675691e0d2cfd346c408cc24fb86f5c2b8'},
  @{id=474;api='IMBMission.FindAgentWithIndex';setterBlock='IL_3ca8';setterAssignment='IL_3cbd';nativeEntry='0x18070b150';registration='0x180645868';evidence='ev_9e9945bb81c2694f4088be078e0583675691e0d2cfd346c408cc24fb86f5c2b8'}
 ); gameTypeMetadata=@{Single=0;MultiClient=1;MultiServer=2;MultiClientServer=3;SingleReplay=4;SingleRecord=5}
}
# Validate profile identity, critical retained CIL and the sentinel arithmetic without executing target code.
foreach($artifact in $r.artifacts){if((Get-FileHash -LiteralPath $artifact.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $artifact.sha256){throw "Artifact changed: $($artifact.path)"}}
if(!($r.methods | Where-Object {$_.signature -match 'get_MaxNumberOfTroopsForMission' -and $_.il -contains 'IL_0006: div'})){throw 'Missing troop-quota evidence'}
if(!($r.methods | Where-Object {$_.signature -match 'AgentHelper::GetAgentIndex' -and $_.il -contains 'IL_0009: ldind.i4'})){throw 'Missing pointer/index evidence'}
if(@($r.capacityConstantCandidates | Where-Object value -eq 2040).Count){throw 'Unexpected managed capacity literal; re-evaluate findings'}
if((-1+(1 -shl 12)-1) -ne 4094 -or (-1+(1 -shl 13)-1) -lt 4095){throw 'Encoding arithmetic failed'}
if((4080+1) -gt (1 -shl 12) -or (4096+1) -le (1 -shl 12)){throw 'Proposed versus alternate capacity encoding check failed'}
$r.validation | Add-Member -Force -NotePropertyMembers @{allArtifactHashesRechecked=$true;criticalIlPresent=$true;sentinelEncodingArithmeticPassed=$true;verifiedUtc=[DateTime]::UtcNow.ToString('o');scope='Static identity/CIL/arithmetic only; no runtime validation'}
$r | ConvertTo-Json -Depth 20 | Set-Content -LiteralPath $ReportPath -Encoding UTF8
@{findings=$r.findings.Count;artifacts=$r.artifacts.Count;methods=$r.methods.Count;targetExecuted=$false;validation='passed-static-only'} | ConvertTo-Json

